5	namespace Doctrine\Persistence;
6	
7	use InvalidArgumentException;
8	use ReflectionClass;
9	
10	use function assert;
11	use function sprintf;
12	
13	/**
14	 * Abstract implementation of the ManagerRegistry contract.
15	 */
16	abstract class AbstractManagerRegistry implements ManagerRegistry
17	{
18	    /**
19	     * @param array<string, string> $connections
20	     * @param array<string, string> $managers
21	     * @phpstan-param class-string $proxyInterfaceName
22	     */
23	    public function __construct(
24	        private readonly string $name,
25	        private array $connections,
26	        private array $managers,
27	        private readonly string $defaultConnection,
28	        private readonly string $defaultManager,
29	        private readonly string $proxyInterfaceName,
30	    ) {
31	    }
32	
33	    /**
34	     * Fetches/creates the given services.
35	     *
36	     * A service in this context is connection or a manager instance.
37	     *
38	     * @param string $name The name of the service.
39	     *
40	     * @return object The instance of the given service.
41	     */
42	    abstract protected function getService(string $name): object;
43	
44	    /**
45	     * Resets the given services.
46	     *
47	     * A service in this context is connection or a manager instance.
48	     *
49	     * @param string $name The name of the service.
50	     */
51	    abstract protected function resetService(string $name): void;
52	
53	    /** Gets the name of the registry. */
54	    public function getName(): string
55	    {
56	        return $this->name;
57	    }
58	
59	    public function getConnection(string|null $name = null): object
60	    {
61	        if ($name === null) {
62	            $name = $this->defaultConnection;
63	        }
64	
65	        if (! isset($this->connections[$name])) {
66	            throw new InvalidArgumentException(
67	                sprintf('Doctrine %s Connection named "%s" does not exist.', $this->name, $name),
68	            );
69	        }
70	
71	        return $this->getService($this->connections[$name]);
72	    }
73	
74	    /**
75	     * {@inheritDoc}
76	     */
77	    public function getConnectionNames(): array
78	    {
79	        return $this->connections;
80	    }
81	
82	    /**
83	     * {@inheritDoc}
84	     */
85	    public function getConnections(): array
86	    {
87	        $connections = [];
88	        foreach ($this->connections as $name => $id) {
89	            $connections[$name] = $this->getService($id);
90	        }
91	
92	        return $connections;
93	    }
94	
95	    public function getDefaultConnectionName(): string
96	    {
97	        return $this->defaultConnection;
98	    }
99	
100	    public function getDefaultManagerName(): string
101	    {
102	        return $this->defaultManager;
103	    }
104	
105	    /**
106	     * {@inheritDoc}
107	     *
108	     * @throws InvalidArgumentException
109	     */
110	    public function getManager(string|null $name = null): ObjectManager
111	    {
112	        if ($name === null) {
113	            $name = $this->defaultManager;
114	        }
115	
116	        if (! isset($this->managers[$name])) {
117	            throw new InvalidArgumentException(
118	                sprintf('Doctrine %s Manager named "%s" does not exist.', $this->name, $name),
119	            );
120	        }
121	
122	        $service = $this->getService($this->managers[$name]);
123	        assert($service instanceof ObjectManager);
124	
125	        return $service;
126	    }
127	
128	    public function getManagerForClass(string $class): ObjectManager|null
129	    {
130	        $proxyClass = new ReflectionClass($class);
131	        if ($proxyClass->isAnonymous()) {
132	            return null;
133	        }
134	
135	        if ($proxyClass->implementsInterface($this->proxyInterfaceName)) {
136	            $parentClass = $proxyClass->getParentClass();
137	
138	            if ($parentClass === false) {
139	                return null;
140	            }
141	
142	            $class = $parentClass->getName();
143	        }
144	
145	        foreach ($this->managers as $id) {
146	            $manager = $this->getService($id);
147	            assert($manager instanceof ObjectManager);
148	
149	            if (! $manager->getMetadataFactory()->isTransient($class)) {
150	                return $manager;
151	            }
152	        }
153	
154	        return null;
155	    }
156	
157	    /**
158	     * {@inheritDoc}
159	     */
160	    public function getManagerNames(): array
161	    {
162	        return $this->managers;
163	    }
164	
165	    /**
166	     * {@inheritDoc}
167	     */
168	    public function getManagers(): array
169	    {
170	        $managers = [];
171	
172	        foreach ($this->managers as $name => $id) {
173	            $manager = $this->getService($id);
174	            assert($manager instanceof ObjectManager);
175	            $managers[$name] = $manager;
176	        }
177	
178	        return $managers;
179	    }
180	
181	    public function getRepository(
182	        string $persistentObject,
183	        string|null $persistentManagerName = null,
184	    ): ObjectRepository {
185	        return $this
186	            ->selectManager($persistentObject, $persistentManagerName)
187	            ->getRepository($persistentObject);
188	    }
189	
190	    public function resetManager(string|null $name = null): ObjectManager
191	    {
192	        if ($name === null) {
193	            $name = $this->defaultManager;
194	        }
195	
196	        if (! isset($this->managers[$name])) {
197	            throw new InvalidArgumentException(sprintf('Doctrine %s Manager named "%s" does not exist.', $this->name, $name));
198	        }
199	
200	        // force the creation of a new document manager
201	        // if the current one is closed
202	        $this->resetService($this->managers[$name]);
203	
204	        return $this->getManager($name);
205	    }
206	
207	    /** @phpstan-param class-string $persistentObject */
208	    private function selectManager(
209	        string $persistentObject,
210	        string|null $persistentManagerName = null,
211	    ): ObjectManager {
212	        if ($persistentManagerName !== null) {
213	            return $this->getManager($persistentManagerName);
214	        }
215	
216	        return $this->getManagerForClass($persistentObject) ?? $this->getManager();
217	    }
218	}
